        pub fn init(allocator: Allocator) !ComprehensiveLexicon {
            var lex = ComprehensiveLexicon{
                .nouns = std.StringHashMap(NounEntry).init(allocator),
                .verbs = std.StringHashMap(VerbEntry).init(allocator),
                .adjectives = std.StringHashMap(AdjectiveEntry).init(allocator),
                .adverbs = std.StringHashMap(AdverbEntry).init(allocator),
                .pronouns = std.StringHashMap(PronounEntry).init(allocator),
                .numerals = std.StringHashMap(NumeralEntry).init(allocator),
                .postpositions = std.StringHashMap(PostpositionEntry).init(allocator),
                .conjunctions = std.StringHashMap(ConjunctionEntry).init(allocator),
                .particles = std.StringHashMap(ParticleEntry).init(allocator),
                .interjections = std.StringHashMap(InterjectionEntry).init(allocator),
            };

            try lex.nouns.ensureTotalCapacity(100000);
            try lex.verbs.ensureTotalCapacity(50000);
            try lex.adjectives.ensureTotalCapacity(30000);
            try lex.adverbs.ensureTotalCapacity(10000);
            try lex.pronouns.ensureTotalCapacity(500);
            try lex.numerals.ensureTotalCapacity(2000);
            try lex.postpositions.ensureTotalCapacity(200);
            try lex.conjunctions.ensureTotalCapacity(100);
            try lex.particles.ensureTotalCapacity(50);
            try lex.interjections.ensureTotalCapacity(500);

            try lex.populateNouns(allocator);
            try lex.populateVerbs(allocator);
            try lex.populateAdjectives(allocator);
            try lex.populateAdverbs(allocator);
            try lex.populatePronouns(allocator);
            try lex.populateNumerals(allocator);
            try lex.populatePostpositions(allocator);
            try lex.populateConjunctions(allocator);
            try lex.populateParticles(allocator);
            try lex.populateInterjections(allocator);

            return lex;
        }

