        pub const PhonologyEngine = struct {
            vowel_classes: std.AutoHashMap(u8, VowelClass),
            assimilation_rules: []AssimilationRule,
            linking_vowel_rules: []LinkingVowelRule,

            pub const VowelClass = enum { FrontUnrounded, FrontRounded, BackUnrounded, BackRounded };

            pub const AssimilationRule = struct {
                context: []const u8,
                target: u8,
                replacement: u8,
            };

            pub const LinkingVowelRule = struct {
                stem_ending: []const u8,
                suffix_beginning: []const u8,
                linking_vowel_front: []const u8,
                linking_vowel_back: []const u8,
            };

            pub fn init(allocator: Allocator) !PhonologyEngine {
                var vowel_map = std.AutoHashMap(u8, VowelClass).init(allocator);
                try vowel_map.put('a', .BackUnrounded);
                try vowel_map.put('á', .BackUnrounded);
                try vowel_map.put('e', .FrontUnrounded);
                try vowel_map.put('é', .FrontUnrounded);
                try vowel_map.put('i', .FrontUnrounded);
                try vowel_map.put('í', .FrontUnrounded);
                try vowel_map.put('o', .BackRounded);
                try vowel_map.put('ó', .BackRounded);
                try vowel_map.put('ö', .FrontRounded);
                try vowel_map.put('ő', .FrontRounded);
                try vowel_map.put('u', .BackRounded);
                try vowel_map.put('ú', .BackRounded);
                try vowel_map.put('ü', .FrontRounded);
                try vowel_map.put('ű', .FrontRounded);

                const assim_rules = try allocator.alloc(AssimilationRule, 10);
                assim_rules[0] = .{ .context = "sz", .target = 't', .replacement = 's' };
                assim_rules[1] = .{ .context = "z", .target = 't', .replacement = 'z' };
                assim_rules[2] = .{ .context = "s", .target = 't', .replacement = 's' };
                assim_rules[3] = .{ .context = "c", .target = 't', .replacement = 'c' };
                assim_rules[4] = .{ .context = "cs", .target = 't', .replacement = 'c' };
                assim_rules[5] = .{ .context = "zs", .target = 't', .replacement = 'z' };
                assim_rules[6] = .{ .context = "j", .target = 't', .replacement = 'j' };
                assim_rules[7] = .{ .context = "ty", .target = 't', .replacement = 't' };
                assim_rules[8] = .{ .context = "gy", .target = 't', .replacement = 'g' };
                assim_rules[9] = .{ .context = "ny", .target = 't', .replacement = 'n' };

                const link_rules = try allocator.alloc(LinkingVowelRule, 5);
                link_rules[0] = .{ .stem_ending = "t", .suffix_beginning = "t", .linking_vowel_front = "e", .linking_vowel_back = "a" };
                link_rules[1] = .{ .stem_ending = "d", .suffix_beginning = "t", .linking_vowel_front = "e", .linking_vowel_back = "a" };
                link_rules[2] = .{ .stem_ending = "n", .suffix_beginning = "t", .linking_vowel_front = "e", .linking_vowel_back = "a" };
                link_rules[3] = .{ .stem_ending = "l", .suffix_beginning = "t", .linking_vowel_front = "e", .linking_vowel_back = "a" };
                link_rules[4] = .{ .stem_ending = "r", .suffix_beginning = "t", .linking_vowel_front = "e", .linking_vowel_back = "a" };

                return .{
                    .vowel_classes = vowel_map,
                    .assimilation_rules = assim_rules,
                    .linking_vowel_rules = link_rules,
                };
            }

            pub fn determineVowelHarmony(self: *const PhonologyEngine, word: []const u8) ComprehensiveLexicon.VowelHarmony {
                var has_front: bool = false;
                var has_back: bool = false;

                for (word) |char| {
                    if (self.vowel_classes.get(char)) |vc| {
                        switch (vc) {
                            .FrontUnrounded, .FrontRounded => has_front = true,
                            .BackUnrounded, .BackRounded => has_back = true,
                        }
                    }
                }

                if (has_front and has_back) return .Mixed;
                if (has_front) return .Front;
                return .Back;
            }

            pub fn applyPhonologicalRules(self: *const PhonologyEngine, stem: []const u8, suffix: []const u8, allocator: Allocator) ![]u8 {
                var result = std.ArrayList(u8).init(allocator);
                try result.appendSlice(stem);

                if (suffix.len > 0 and stem.len > 0) {
                    const last_stem_char = stem[stem.len - 1];
                    const first_suffix_char = suffix[0];

                    for (self.assimilation_rules) |rule| {
                        if (rule.target == first_suffix_char) {
                            if (std.mem.endsWith(u8, stem, rule.context)) {
                                try result.append(rule.replacement);
                                if (suffix.len > 1) {
                                    try result.appendSlice(suffix[1..]);
                                }
                                return result.toOwnedSlice();
                            }
                        }
                    }

                    const harmony = self.determineVowelHarmony(stem);
                    for (self.linking_vowel_rules) |rule| {
                        if (std.mem.endsWith(u8, stem, rule.stem_ending) and std.mem.startsWith(u8, suffix, rule.suffix_beginning)) {
                            const linking = if (harmony == .Front) rule.linking_vowel_front else rule.linking_vowel_back;
                            try result.appendSlice(linking);
                            break;
                        }
                    }
                }

                try result.appendSlice(suffix);
                return result.toOwnedSlice();
            }

            pub fn deinit(self: *PhonologyEngine, allocator: Allocator) void {
                self.vowel_classes.deinit();
                allocator.free(self.assimilation_rules);
                allocator.free(self.linking_vowel_rules);
            }
        };

        pub fn init(allocator: Allocator) !MorphologyEngine {
            return .{
                .allocator = allocator,
                .suffix_db = SuffixDatabase.init(),
                .phonology = try PhonologyEngine.init(allocator),
            };
        }

        pub fn analyzeMorphology(self: *const MorphologyEngine, word: []const u8, lexicon: *const ComprehensiveLexicon, allocator: Allocator) !MorphologicalAnalysis {
            var analysis = MorphologicalAnalysis.init(allocator);

            var stem_len = word.len;
            while (stem_len > 0) : (stem_len -= 1) {
                const candidate = word[0..stem_len];

                if (lexicon.nouns.get(candidate)) |entry| {
                    analysis.lemma = try allocator.dupe(u8, entry.lemma);
                    analysis.pos = .Noun;
                    analysis.vowel_harmony = entry.vowel_harmony;
                    if (stem_len < word.len) {
                        const suffix_part = word[stem_len..];
                        try self.parseSuffixes(suffix_part, &analysis);
                    }
                    return analysis;
                }

                if (lexicon.verbs.get(candidate)) |entry| {
                    analysis.lemma = try allocator.dupe(u8, entry.lemma);
                    analysis.pos = .Verb;
                    analysis.vowel_harmony = entry.vowel_harmony;
                    if (stem_len < word.len) {
                        const suffix_part = word[stem_len..];
                        try self.parseSuffixes(suffix_part, &analysis);
                    }
                    return analysis;
                }

                if (lexicon.adjectives.get(candidate)) |entry| {
                    analysis.lemma = try allocator.dupe(u8, entry.lemma);
                    analysis.pos = .Adjective;
                    analysis.vowel_harmony = entry.vowel_harmony;
                    if (stem_len < word.len) {
                        const suffix_part = word[stem_len..];
                        try self.parseSuffixes(suffix_part, &analysis);
                    }
                    return analysis;
                }

                if (lexicon.pronouns.get(candidate)) |_| {
                    analysis.lemma = try allocator.dupe(u8, candidate);
                    analysis.pos = .Pronoun;
                    analysis.vowel_harmony = self.phonology.determineVowelHarmony(candidate);
                    if (stem_len < word.len) {
                        const suffix_part = word[stem_len..];
                        try self.parseSuffixes(suffix_part, &analysis);
                    }
                    return analysis;
                }
            }

            analysis.lemma = try allocator.dupe(u8, word);
            analysis.pos = .Unknown;
            analysis.vowel_harmony = self.phonology.determineVowelHarmony(word);

            return analysis;
        }

        fn parseSuffixes(self: *const MorphologyEngine, suffix_string: []const u8, analysis: *MorphologicalAnalysis) !void {
            var remaining = suffix_string;

            for (self.suffix_db.case_suffixes) |case_set| {
                if (std.mem.eql(u8, remaining, case_set.front_unrounded) or
                    std.mem.eql(u8, remaining, case_set.front_rounded) or
                    std.mem.eql(u8, remaining, case_set.back_unrounded) or
                    std.mem.eql(u8, remaining, case_set.back_rounded))
                {
                    try analysis.morphemes.append(.{ .morph_type = .Case, .value = case_set.case_name });
                    return;
                }
            }

            if (std.mem.eql(u8, remaining, "ek") or std.mem.eql(u8, remaining, "ok") or std.mem.eql(u8, remaining, "k")) {
                try analysis.morphemes.append(.{ .morph_type = .Plural, .value = "plural" });
                return;
            }
        }

        pub fn synthesizeMorphology(self: *const MorphologyEngine, lemma: []const u8, morphemes: []const Morpheme, harmony: ComprehensiveLexicon.VowelHarmony, allocator: Allocator) ![]u8 {
            var result = std.ArrayList(u8).init(allocator);
            try result.appendSlice(lemma);

            for (morphemes) |morph| {
                switch (morph.morph_type) {
                    .Plural => {
                        const suffix = if (harmony == .Front) "ek" else "ok";
                        const combined = try self.phonology.applyPhonologicalRules(result.items, suffix, allocator);
                        result.clearRetainingCapacity();
                        try result.appendSlice(combined);
                        allocator.free(combined);
                    },
                    .Case => {
                        for (self.suffix_db.case_suffixes) |case_set| {
                            if (std.mem.eql(u8, case_set.case_name, morph.value)) {
                                const suffix = if (harmony == .Front) case_set.front_unrounded else case_set.back_unrounded;
                                const combined = try self.phonology.applyPhonologicalRules(result.items, suffix, allocator);
                                result.clearRetainingCapacity();
                                try result.appendSlice(combined);
                                allocator.free(combined);
                                break;
                            }
                        }
                    },
                    .Possessive => {},
                    .VerbConjugation => {},
                }
            }

            return result.toOwnedSlice();
        }

        pub const PartOfSpeech = enum { Noun, Verb, Adjective, Adverb, Pronoun, Numeral, Postposition, Conjunction, Particle, Interjection, Unknown };

        pub const Morpheme = struct {
            morph_type: MorphemeType,
            value: []const u8,

            pub const MorphemeType = enum { Plural, Case, Possessive, VerbConjugation };
        };

