            dep_rules[1] = .{ .head_pos = .Verb, .dependent_pos = .Noun, .relation_type = .Object, .direction = .DependentFirst };
            dep_rules[2] = .{ .head_pos = .Noun, .dependent_pos = .Adjective, .relation_type = .Modifier, .direction = .DependentFirst };
            dep_rules[3] = .{ .head_pos = .Verb, .dependent_pos = .Adverb, .relation_type = .Adverbial, .direction = .DependentFirst };
            dep_rules[4] = .{ .head_pos = .Noun, .dependent_pos = .Numeral, .relation_type = .Determiner, .direction = .DependentFirst };
            dep_rules[5] = .{ .head_pos = .Noun, .dependent_pos = .Noun, .relation_type = .Modifier, .direction = .DependentFirst };
            dep_rules[6] = .{ .head_pos = .Verb, .dependent_pos = .Verb, .relation_type = .Complement, .direction = .DependentFirst };
