            dep_rules[8] = .{ .head_pos = .Verb, .dependent_pos = .Postposition, .relation_type = .Adverbial, .direction = .DependentFirst };
            dep_rules[9] = .{ .head_pos = .Noun, .dependent_pos = .Postposition, .relation_type = .Modifier, .direction = .HeadFirst };
            dep_rules[10] = .{ .head_pos = .Verb, .dependent_pos = .Conjunction, .relation_type = .Conjunction, .direction = .Free };
            dep_rules[11] = .{ .head_pos = .Noun, .dependent_pos = .Conjunction, .relation_type = .Conjunction, .direction = .Free };
            dep_rules[12] = .{ .head_pos = .Adjective, .dependent_pos = .Conjunction, .relation_type = .Conjunction, .direction = .Free };
            dep_rules[13] = .{ .head_pos = .Verb, .dependent_pos = .Particle, .relation_type = .Modifier, .direction = .DependentFirst };
            dep_rules[14] = .{ .head_pos = .Noun, .dependent_pos = .Pronoun, .relation_type = .Modifier, .direction = .DependentFirst };
            dep_rules[15] = .{ .head_pos = .Verb, .dependent_pos = .Pronoun, .relation_type = .Subject, .direction = .Free };
            dep_rules[16] = .{ .head_pos = .Verb, .dependent_pos = .Pronoun, .relation_type = .Object, .direction = .DependentFirst };
            dep_rules[17] = .{ .head_pos = .Adverb, .dependent_pos = .Adverb, .relation_type = .Modifier, .direction = .DependentFirst };
            dep_rules[18] = .{ .head_pos = .Adjective, .dependent_pos = .Adjective, .relation_type = .Modifier, .direction = .DependentFirst };
            dep_rules[19] = .{ .head_pos = .Noun, .dependent_pos = .Noun, .relation_type = .Complement, .direction = .HeadFirst };

            const phrase_rules = try allocator.alloc(PhraseStructureRule, 6);

            const np_constituents = try allocator.alloc(PhraseStructureRule.ConstituentConstraint, 3);
            np_constituents[0] = .{ .category = .Adjective, .optional = true };
            np_constituents[1] = .{ .category = .Numeral, .optional = true };
            np_constituents[2] = .{ .category = .Noun, .optional = false };
            phrase_rules[0] = .{ .phrase_type = .NounPhrase, .constituents = np_constituents, .head_position = 2 };

            const vp_constituents = try allocator.alloc(PhraseStructureRule.ConstituentConstraint, 2);
            vp_constituents[0] = .{ .category = .Adverb, .optional = true };
            vp_constituents[1] = .{ .category = .Verb, .optional = false };
            phrase_rules[1] = .{ .phrase_type = .VerbPhrase, .constituents = vp_constituents, .head_position = 1 };

            const adjp_constituents = try allocator.alloc(PhraseStructureRule.ConstituentConstraint, 2);
            adjp_constituents[0] = .{ .category = .Adverb, .optional = true };
            adjp_constituents[1] = .{ .category = .Adjective, .optional = false };
            phrase_rules[2] = .{ .phrase_type = .AdjectivalPhrase, .constituents = adjp_constituents, .head_position = 1 };

            const advp_constituents = try allocator.alloc(PhraseStructureRule.ConstituentConstraint, 2);
            advp_constituents[0] = .{ .category = .Adverb, .optional = true };
            advp_constituents[1] = .{ .category = .Adverb, .optional = false };
            phrase_rules[3] = .{ .phrase_type = .AdverbialPhrase, .constituents = advp_constituents, .head_position = 1 };

            const pp_constituents = try allocator.alloc(PhraseStructureRule.ConstituentConstraint, 2);
            pp_constituents[0] = .{ .category = .Noun, .optional = false };
            pp_constituents[1] = .{ .category = .Postposition, .optional = false };
            phrase_rules[4] = .{ .phrase_type = .PrepositionalPhrase, .constituents = pp_constituents, .head_position = 1 };

            const s_constituents = try allocator.alloc(PhraseStructureRule.ConstituentConstraint, 2);
            s_constituents[0] = .{ .category = .Noun, .optional = true };
            s_constituents[1] = .{ .category = .Verb, .optional = false };
            phrase_rules[5] = .{ .phrase_type = .Sentence, .constituents = s_constituents, .head_position = 1 };

            return .{
                .allocator = allocator,
                .dependency_rules = dep_rules,
                .phrase_structure_rules = phrase_rules,
            };
        }

        pub fn parseSentence(self: *const SyntaxEngine, words: []const MorphologyEngine.MorphologicalAnalysis, allocator: Allocator) !SyntacticParse {
            var parse = SyntacticParse.init(allocator);

            var verb_index: ?usize = null;
            for (words, 0..) |word, i| {
                if (word.pos == .Verb) {
                    verb_index = i;
                    break;
                }
            }

            if (verb_index) |vi| {
                try parse.dependencies.append(.{
                    .head_index = vi,
                    .dependent_index = vi,
                    .relation = .Subject,
                });

                var i: usize = 0;
                while (i < words.len) : (i += 1) {
                    if (i == vi) continue;

                    const word = words[i];
                    for (self.dependency_rules) |rule| {
                        if (rule.head_pos == words[vi].pos and rule.dependent_pos == word.pos) {
                            try parse.dependencies.append(.{
                                .head_index = vi,
                                .dependent_index = i,
                                .relation = rule.relation_type,
                            });
                            break;
                        }
                    }
                }
            }

            return parse;
        }

        pub const SyntacticParse = struct {
            dependencies: std.ArrayList(Dependency),
            phrases: std.ArrayList(Phrase),

            pub const Dependency = struct {
                head_index: usize,
                dependent_index: usize,
                relation: DependencyRule.RelationType,
            };

            pub const Phrase = struct {
                phrase_type: PhraseStructureRule.PhraseType,
                start_index: usize,
                end_index: usize,
                head_index: usize,
            };

            pub fn init(allocator: Allocator) SyntacticParse {
                return .{
                    .dependencies = std.ArrayList(Dependency).init(allocator),
                    .phrases = std.ArrayList(Phrase).init(allocator),
                };
            }

            pub fn deinit(self: *SyntacticParse) void {
                self.dependencies.deinit();
                self.phrases.deinit();
            }
        };

        pub fn deinit(self: *SyntaxEngine) void {
            self.allocator.free(self.dependency_rules);
            for (self.phrase_structure_rules) |rule| {
                self.allocator.free(rule.constituents);
            }
            self.allocator.free(self.phrase_structure_rules);
        }
    };

    pub const SemanticEngine = struct {
        allocator: Allocator,
        semantic_frames: std.StringHashMap(SemanticFrame),

        pub const SemanticFrame = struct {
            frame_name: []const u8,
            core_roles: []const SemanticRole,
            peripheral_roles: []const SemanticRole,

            pub const SemanticRole = struct {
                role_name: []const u8,
                constraints: []const Constraint,

                pub const Constraint = enum { Animate, Inanimate, Human, Concrete, Abstract, Event, State };
            };
        };

        pub fn init(allocator: Allocator) !SemanticEngine {
            var frames = std.StringHashMap(SemanticFrame).init(allocator);
            try frames.ensureTotalCapacity(100);

            return .{
                .allocator = allocator,
                .semantic_frames = frames,
            };
        }

        pub fn analyzeSemantics(self: *const SemanticEngine, syntax: *const SyntaxEngine.SyntacticParse, words: []const MorphologyEngine.MorphologicalAnalysis, allocator: Allocator) !SemanticRepresentation {
            var repr = SemanticRepresentation.init(allocator);

            for (syntax.dependencies.items) |dep| {
                const head = words[dep.head_index];
                const dependent = words[dep.dependent_index];

                const pred = Predicate{
                    .predicate_name = try allocator.dupe(u8, head.lemma),
                    .arguments = try allocator.alloc(Argument, 1),
                };
                pred.arguments[0] = .{
                    .role = switch (dep.relation) {
                        .Subject => "Agent",
                        .Object => "Theme",
                        .IndirectObject => "Recipient",
                        else => "Other",
                    },
                    .value = try allocator.dupe(u8, dependent.lemma),
                };

                try repr.predicates.append(pred);
            }

            return repr;
        }

        pub const SemanticRepresentation = struct {
            predicates: std.ArrayList(Predicate),

            pub const Predicate = struct {
                predicate_name: []const u8,
                arguments: []Argument,
            };

            pub const Argument = struct {
                role: []const u8,
                value: []const u8,
            };

            pub fn init(allocator: Allocator) SemanticRepresentation {
                return .{
                    .predicates = std.ArrayList(Predicate).init(allocator),
                };
            }

            pub fn deinit(self: *SemanticRepresentation, allocator: Allocator) void {
                for (self.predicates.items) |pred| {
                    allocator.free(pred.predicate_name);
                    for (pred.arguments) |arg| {
                        allocator.free(arg.value);
                    }
                    allocator.free(pred.arguments);
                }
                self.predicates.deinit();
            }
        };

        pub fn deinit(self: *SemanticEngine) void {
            var iter = self.semantic_frames.iterator();
            while (iter.next()) |_| {}
            self.semantic_frames.deinit();
        }
    };

    pub const EmbeddingGenerator = struct {
        allocator: Allocator,
        embedding_dim: usize,
        vocab_embeddings: std.StringHashMap([]f32),

        pub fn init(allocator: Allocator, embedding_dim: usize) !EmbeddingGenerator {
            return .{
                .allocator = allocator,
                .embedding_dim = embedding_dim,
                .vocab_embeddings = std.StringHashMap([]f32).init(allocator),
            };
        }

        pub fn generateEmbedding(self: *EmbeddingGenerator, word: []const u8, morph_analysis: *const MorphologyEngine.MorphologicalAnalysis) ![]f32 {
            if (self.vocab_embeddings.get(word)) |existing| {
                const copy = try self.allocator.alloc(f32, existing.len);
                @memcpy(copy, existing);
                return copy;
            }

            const embedding = try self.allocator.alloc(f32, self.embedding_dim);

            var seed: u64 = 0;
            for (word, 0..) |char, i| {
                seed +%= @as(u64, char) *% (@as(u64, i) +% 1);
            }

            var prng = std.rand.DefaultPrng.init(seed);
            const random = prng.random();

            for (embedding, 0..) |*val, i| {
                val.* = (random.float(f32) * 2.0 - 1.0) * 0.1;

                if (i < 10) {
                    switch (morph_analysis.pos) {
                        .Noun => val.* += 0.3,
                        .Verb => val.* += 0.5,
                        .Adjective => val.* += 0.2,
                        .Adverb => val.* += 0.15,
                        else => {},
                    }
                }

                if (i >= 10 and i < 20) {
                    switch (morph_analysis.vowel_harmony) {
                        .Front => val.* += 0.2,
                        .Back => val.* -= 0.2,
                        .Mixed => val.* += 0.05,
                        .Neutral => {},
                    }
                }

                if (i >= 20 and i < 30) {
                    for (morph_analysis.morphemes.items, 0..) |morph, mi| {
                        switch (morph.morph_type) {
                            .Plural => val.* += 0.1 * @as(f32, @floatFromInt(mi + 1)),
                            .Case => val.* += 0.15 * @as(f32, @floatFromInt(mi + 1)),
                            .Possessive => val.* += 0.12 * @as(f32, @floatFromInt(mi + 1)),
                            .VerbConjugation => val.* += 0.18 * @as(f32, @floatFromInt(mi + 1)),
                        }
                    }
                }
            }

            var norm: f32 = 0.0;
            for (embedding) |val| {
                norm += val * val;
            }
            norm = @sqrt(norm);

            if (norm > 0.0) {
                for (embedding) |*val| {
                    val.* /= norm;
                }
            }

            const stored = try self.allocator.alloc(f32, embedding.len);
            @memcpy(stored, embedding);
            try self.vocab_embeddings.put(try self.allocator.dupe(u8, word), stored);

            return embedding;
        }

        pub fn generateSentenceEmbedding(self: *EmbeddingGenerator, word_embeddings: []const []const f32) ![]f32 {
            const sentence_emb = try self.allocator.alloc(f32, self.embedding_dim);
            @memset(sentence_emb, 0.0);

            for (word_embeddings) |word_emb| {
                for (word_emb, 0..) |val, i| {
                    sentence_emb[i] += val;
                }
            }

            const count: f32 = @floatFromInt(word_embeddings.len);
            for (sentence_emb) |*val| {
                val.* /= count;
            }

            var norm: f32 = 0.0;
            for (sentence_emb) |val| {
                norm += val * val;
            }
            norm = @sqrt(norm);

            if (norm > 0.0) {
                for (sentence_emb) |*val| {
                    val.* /= norm;
                }
            }

            return sentence_emb;
        }

        pub fn deinit(self: *EmbeddingGenerator) void {
            var iter = self.vocab_embeddings.iterator();
            while (iter.next()) |kv| {
                self.allocator.free(kv.key_ptr.*);
                self.allocator.free(kv.value_ptr.*);
            }
            self.vocab_embeddings.deinit();
        }
    };

    pub fn init(allocator: Allocator) !HungarianLinguisticCore {
        return .{
            .allocator = allocator,
            .morphology = try MorphologyEngine.init(allocator),
            .syntax = try SyntaxEngine.init(allocator),
            .semantics = try SemanticEngine.init(allocator),
            .lexicon = try ComprehensiveLexicon.init(allocator),
            .embedding_generator = try EmbeddingGenerator.init(allocator, 512),
        };
    }

    pub fn processSentence(self: *HungarianLinguisticCore, sentence: []const u8) !LinguisticAnalysis {
        var tokens = std.ArrayList([]const u8).init(self.allocator);
        defer tokens.deinit();

        var token_iter = std.mem.tokenizeAny(u8, sentence, " \t\n\r,.!?;:");
        while (token_iter.next()) |token| {
            try tokens.append(token);
        }

        var morph_analyses = std.ArrayList(MorphologyEngine.MorphologicalAnalysis).init(self.allocator);
        defer {
            for (morph_analyses.items) |*analysis| {
                analysis.deinit(self.allocator);
            }
            morph_analyses.deinit();
        }

        for (tokens.items) |token| {
            const analysis = try self.morphology.analyzeMorphology(token, &self.lexicon, self.allocator);
            try morph_analyses.append(analysis);
        }

        const syntax_parse = try self.syntax.parseSentence(morph_analyses.items, self.allocator);

        const semantic_repr = try self.semantics.analyzeSemantics(&syntax_parse, morph_analyses.items, self.allocator);

        var word_embeddings = std.ArrayList([]f32).init(self.allocator);
        defer {
            for (word_embeddings.items) |emb| {
                self.allocator.free(emb);
            }
            word_embeddings.deinit();
        }

        for (morph_analyses.items, 0..) |*analysis, i| {
            const embedding = try self.embedding_generator.generateEmbedding(tokens.items[i], analysis);
            try word_embeddings.append(embedding);
        }

        const sentence_embedding = try self.embedding_generator.generateSentenceEmbedding(word_embeddings.items);

        return LinguisticAnalysis{
            .syntax = syntax_parse,
            .semantics = semantic_repr,
            .sentence_embedding = sentence_embedding,
        };
    }

    pub const LinguisticAnalysis = struct {
        syntax: SyntaxEngine.SyntacticParse,
        semantics: SemanticEngine.SemanticRepresentation,
        sentence_embedding: []f32,

        pub fn deinit(self: *LinguisticAnalysis, allocator: Allocator) void {
            self.syntax.deinit();
            self.semantics.deinit(allocator);
            allocator.free(self.sentence_embedding);
        }
    };

    pub fn deinit(self: *HungarianLinguisticCore) void {
        self.morphology.deinit();
        self.syntax.deinit();
        self.semantics.deinit();
        self.lexicon.deinit();
        self.embedding_generator.deinit();
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    var core = try HungarianLinguisticCore.init(allocator);
    defer core.deinit();

    const test_sentence = "a nagy ház ablaka piros";
    var analysis = try core.processSentence(test_sentence);
    defer analysis.deinit(allocator);

    const stdout = std.io.getStdOut().writer();
    try stdout.print("Magyar nyelvfeldolgozó rendszer inicializálva\n", .{});
    try stdout.print("Mondatelemzés kész: {s}\n", .{test_sentence});
    try stdout.print("Függőségi elemek száma: {d}\n", .{analysis.syntax.dependencies.items.len});
    try stdout.print("Szemantikai predikátumok száma: {d}\n", .{analysis.semantics.predicates.items.len});
    try stdout.print("Mondatbeágyazás dimenziója: {d}\n", .{analysis.sentence_embedding.len});
}
