pub const HungarianAGICore = struct {
    allocator: Allocator,
    lexicon: Lexicon,
    morphology: MorphologicalAnalyzer,
    syntax: FunctionalSyntaxParser,
    semantics: SemanticProjector,

    pub const VowelHarmony = enum {
        FrontUnrounded,
        FrontRounded,
        Back,
        Neutral,
        Mixed
    };

    pub const PartOfSpeech = enum {
        Noun,
        Verb,
        Adjective,
        Adverb,
        Postposition,
        Numeral,
        Pronoun,
        Conjunction,
        Particle,
        Unknown
    };

    pub const SemanticFeature = enum {
        Animate,
        Inanimate,
        Human,
        Concrete,
        Abstract,
        Motion,
        State,
        Time,
        Location,
        PhysicalObject,
        MentalProcess,
        Communication,
        SentimentPositive,
        SentimentNegative
    };

    pub const SuffixType = enum {
        Plural,
        Possessive,
        Case,
        Tense,
        Mood,
        Person,
        Derivational
    };

    pub const Lexicon = struct {
        entries: std.StringHashMap(LexicalEntry),
        stem_redirects: std.StringHashMap([]const u8),
        allocator: Allocator,

        pub const LexicalEntry = struct {
            lemma: []const u8,
            pos: PartOfSpeech,
            harmony: VowelHarmony,
            features: std.ArrayList(SemanticFeature),
            argument_structure: std.ArrayList(CaseType),
        };

        pub fn init(allocator: Allocator) Lexicon {
            return .{
                .entries = std.StringHashMap(LexicalEntry).init(allocator),
                .stem_redirects = std.StringHashMap([]const u8).init(allocator),
                .allocator = allocator,
            };
        }

        pub fn deinit(self: *Lexicon) void {
            var iter = self.entries.iterator();
            while (iter.next()) |entry| {
                entry.value_ptr.features.deinit();
                entry.value_ptr.argument_structure.deinit();
            }
            self.entries.deinit();
            self.stem_redirects.deinit();
        }

        pub fn addEntry(self: *Lexicon, lemma: []const u8, pos: PartOfSpeech, harmony: VowelHarmony, features: []const SemanticFeature) !void {
            var feature_list = std.ArrayList(SemanticFeature).init(self.allocator);
            try feature_list.appendSlice(features);

            try self.entries.put(lemma, LexicalEntry{
                .lemma = lemma,
                .pos = pos,
                .harmony = harmony,
                .features = feature_list,
                .argument_structure = std.ArrayList(CaseType).init(self.allocator),
            });
        }

        pub fn addIrregularStem(self: *Lexicon, stem: []const u8, lemma: []const u8) !void {
            try self.stem_redirects.put(stem, lemma);
        }

        pub fn lookup(self: *const Lexicon, word: []const u8) ?LexicalEntry {
            if (self.entries.get(word)) |entry| {
                return LexicalEntry{
                    .lemma = entry.lemma,
                    .pos = entry.pos,
                    .harmony = entry.harmony,
                    .features = entry.features, 
                    .argument_structure = entry.argument_structure
                };
            }
            if (self.stem_redirects.get(word)) |lemma| {
                if (self.entries.get(lemma)) |entry| {
                    return LexicalEntry{
                        .lemma = entry.lemma,
                        .pos = entry.pos,
                        .harmony = entry.harmony,
                        .features = entry.features,
                        .argument_structure = entry.argument_structure
                    };
                }
            }
            return null;
        }
    };

    pub const MorphologicalAnalyzer = struct {
        allocator: Allocator,
        suffixes: std.ArrayList(SuffixRule),

        pub const SuffixRule = struct {
            surface: []const u8,
            canonical: []const u8,
            type: SuffixType,
            harmony_req: VowelHarmony,
            precedence: u8, 
        };

        pub const MorphResult = struct {
            root: []const u8,
            pos: PartOfSpeech,
            tags: std.ArrayList(MorphTag),
            valid: bool,
        };

        pub const MorphTag = struct {
            type: SuffixType,
            value: []const u8,
        };

        pub fn init(allocator: Allocator) !MorphologicalAnalyzer {
            var ma = MorphologicalAnalyzer{
                .allocator = allocator,
                .suffixes = std.ArrayList(SuffixRule).init(allocator),
            };
            try ma.populateSuffixes();
            return ma;
        }

        pub fn deinit(self: *MorphologicalAnalyzer) void {
            self.suffixes.deinit();
        }

        fn populateSuffixes(self: *MorphologicalAnalyzer) !void {
            try self.addSuffix("k", "plural", .Plural, .Neutral, 10);
            try self.addSuffix("ak", "plural", .Plural, .Back, 10);
            try self.addSuffix("ok", "plural", .Plural, .Back, 10);
            try self.addSuffix("ek", "plural", .Plural, .FrontUnrounded, 10);
            try self.addSuffix("ök", "plural", .Plural, .FrontRounded, 10);

            try self.addSuffix("t", "acc", .Case, .Neutral, 30);
            try self.addSuffix("at", "acc", .Case, .Back, 30);
            try self.addSuffix("ot", "acc", .Case, .Back, 30);
            try self.addSuffix("et", "acc", .Case, .FrontUnrounded, 30);
            try self.addSuffix("öt", "acc", .Case, .FrontRounded, 30);

            try self.addSuffix("ban", "ine", .Case, .Back, 30);
            try self.addSuffix("ben", "ine", .Case, .FrontUnrounded, 30);

            try self.addSuffix("nak", "dat", .Case, .Back, 30);
            try self.addSuffix("nek", "dat", .Case, .FrontUnrounded, 30);

            try self.addSuffix("m", "poss_1sg", .Possessive, .Neutral, 20);
            try self.addSuffix("om", "poss_1sg", .Possessive, .Back, 20);
            try self.addSuffix("em", "poss_1sg", .Possessive, .FrontUnrounded, 20);
            try self.addSuffix("öm", "poss_1sg", .Possessive, .FrontRounded, 20);
        }

        fn addSuffix(self: *MorphologicalAnalyzer, surface: []const u8, canonical: []const u8, stype: SuffixType, harmony: VowelHarmony, prec: u8) !void {
            try self.suffixes.append(SuffixRule{
                .surface = surface,
                .canonical = canonical,
                .type = stype,
                .harmony_req = harmony,
                .precedence = prec,
            });
        }

        pub fn analyze(self: *const MorphologicalAnalyzer, lexicon: *const Lexicon, word: []const u8) !MorphResult {
            var result = MorphResult{
                .root = "",
                .pos = .Unknown,
                .tags = std.ArrayList(MorphTag).init(self.allocator),
                .valid = false,
            };

            if (lexicon.lookup(word)) |entry| {
                result.root = entry.lemma;
                result.pos = entry.pos;
                result.valid = true;
                return result;
            }

            try self.recursiveStrip(lexicon, word, &result, 100); 
            return result;
        }

        fn recursiveStrip(self: *const MorphologicalAnalyzer, lexicon: *const Lexicon, current_form: []const u8, result: *MorphResult, max_prec: u8) !void {
            if (lexicon.lookup(current_form)) |entry| {
                result.root = entry.lemma;
                result.pos = entry.pos;
                result.valid = true;
                return;
            }

            for (self.suffixes.items) |suffix| {
                if (suffix.precedence > max_prec) continue;

                if (std.mem.endsWith(u8, current_form, suffix.surface)) {
                    const stem_len = current_form.len - suffix.surface.len;
                    if (stem_len < 2) continue; 

                    const candidate_stem = current_form[0..stem_len];
                    const stem_harmony = determineHarmony(candidate_stem);

                    if (isHarmonyCompatible(stem_harmony, suffix.harmony_req)) {

                        var temp_result = MorphResult{
                            .root = "",
                            .pos = .Unknown,
                            .tags = std.ArrayList(MorphTag).init(self.allocator),
                            .valid = false,
                        };
                        defer temp_result.tags.deinit();

                        try self.recursiveStrip(lexicon, candidate_stem, &temp_result, suffix.precedence);

                        if (temp_result.valid) {
                            result.root = temp_result.root;
                            result.pos = temp_result.pos;
                            result.valid = true;

                            for (temp_result.tags.items) |tag| {
                                try result.tags.append(tag);
                            }
                            try result.tags.append(MorphTag{ .type = suffix.type, .value = suffix.canonical });
                            return;
                        }
                    }
                }
            }
        }
    };

    pub const CaseType = enum {
        Nominative,
        Accusative,
        Dative,
        Inessive,
        Illative,
        Elative,
        Superessive,
        Sublative,
        Delative,
        Adessive,
        Allative,
        Ablative,
        Instrumental,
        Causal,
        Translative,
        Terminative
    };

    pub const FunctionalSyntaxParser = struct {
        allocator: Allocator,

        pub const DependencyType = enum {
            Subject,
            Object,
            IndirectObject,
            Location,
            Possessor,
            Attribute,
            Determiner,
            Predicate,
            Focus,
            Topic,
            Unknown
        };

        pub const SyntaxNode = struct {
            token_index: usize,
            head_index: ?usize,
            dependency: DependencyType,
        };

        pub fn init(allocator: Allocator) FunctionalSyntaxParser {
            return .{ .allocator = allocator };
        }

        pub fn parse(self: *FunctionalSyntaxParser, analyses: []const MorphologicalAnalyzer.MorphResult) !std.ArrayList(SyntaxNode) {
            var nodes = std.ArrayList(SyntaxNode).init(self.allocator);
            var verb_idx: ?usize = null;
            var focus_idx: ?usize = null;

            for (analyses, 0..) |word, i| {
                try nodes.append(SyntaxNode{
                    .token_index = i,
                    .head_index = null,
                    .dependency = .Unknown,
                });
                if (word.pos == .Verb) {
                    verb_idx = i;
                }
            }

            if (verb_idx) |v_idx| {
                nodes.items[v_idx].dependency = .Predicate;

                if (v_idx > 0) {
                    var i = v_idx - 1;
                    if (analyses[i].pos != .Conjunction and analyses[i].pos != .Particle) {
                        focus_idx = i;
                        nodes.items[i].dependency = .Focus;
                        nodes.items[i].head_index = v_idx;
                    }
                }

                for (analyses, 0..) |word, i| {
                    if (i == v_idx) continue;
                    if (focus_idx != null and i == focus_idx.?) continue;

                    if (word.pos == .Noun or word.pos == .Pronoun or word.pos == .Numeral) {
                        nodes.items[i].head_index = v_idx;

                        var case_found = false;
                        for (word.tags.items) |tag| {
                            if (tag.type == .Case) {
                                case_found = true;
                                if (std.mem.eql(u8, tag.value, "acc")) {
                                    nodes.items[i].dependency = .Object;
                                } else if (std.mem.eql(u8, tag.value, "dat")) {
                                    nodes.items[i].dependency = .IndirectObject;
                                } else if (std.mem.eql(u8, tag.value, "ine")) {
                                    nodes.items[i].dependency = .Location;
                                } else {
                                    nodes.items[i].dependency = .Unknown;
                                }
                            }
                        }
                        if (!case_found) {
                            nodes.items[i].dependency = .Subject;
                        }
                    } else if (word.pos == .Adjective) {
                        if (i + 1 < analyses.len and (analyses[i+1].pos == .Noun)) {
                            nodes.items[i].head_index = i + 1;
                            nodes.items[i].dependency = .Attribute;
                        }
                    }
                }
            }
            return nodes;
        }
    };

    pub const SemanticProjector = struct {
        allocator: Allocator,
        feature_embeddings: std.AutoHashMap(SemanticFeature, [128]f32),
        pos_embeddings: std.AutoHashMap(PartOfSpeech, [128]f32),

        pub fn init(allocator: Allocator) !SemanticProjector {
            var sp = SemanticProjector{
                .allocator = allocator,
                .feature_embeddings = std.AutoHashMap(SemanticFeature, [128]f32).init(allocator),
                .pos_embeddings = std.AutoHashMap(PartOfSpeech, [128]f32).init(allocator),
            };
            try sp.initializeBaseVectors();
            return sp;
        }

        pub fn deinit(self: *SemanticProjector) void {
            self.feature_embeddings.deinit();
            self.pos_embeddings.deinit();
        }

        fn initializeBaseVectors(self: *SemanticProjector) !void {
            var prng = std.rand.DefaultPrng.init(0xCAFEBABE);
            const random = prng.random();

            const features = std.meta.tags(SemanticFeature);
            for (features) |f| {
                var vec: [128]f32 = undefined;
                for (0..128) |i| {
                    vec[i] = random.float(f32) * 2.0 - 1.0;
                }
                try self.feature_embeddings.put(f, vec);
            }

            const poses = std.meta.tags(PartOfSpeech);
            for (poses) |p| {
                var vec: [128]f32 = undefined;
                for (0..128) |i| {
                    vec[i] = random.float(f32) * 2.0 - 1.0;
                }
                try self.pos_embeddings.put(p, vec);
            }
        }

        pub fn project(self: *SemanticProjector, analysis: MorphologicalAnalyzer.MorphResult, lexicon: *const Lexicon) ![128]f32 {
            var embedding: [128]f32 = .{0} ** 128;

            if (self.pos_embeddings.get(analysis.pos)) |pos_vec| {
                addVec(&embedding, &pos_vec, 0.5);
            }

            if (lexicon.lookup(analysis.root)) |entry| {
                for (entry.features.items) |feat| {
                    if (self.feature_embeddings.get(feat)) |feat_vec| {
                        addVec(&embedding, &feat_vec, 1.0);
                    }
                }
            }

            for (analysis.tags.items) |tag| {
                if (tag.type == .Plural) {
                    modifyVec(&embedding, 0.1); 
                }
                if (tag.type == .Case) {
                    modifyVec(&embedding, 0.2); 
                }
            }

            normalize(&embedding);
            return embedding;
        }
    };

    fn determineHarmony(word: []const u8) VowelHarmony {
        var back_count: usize = 0;
        var front_count: usize = 0;
        var round_count: usize = 0;

        for (word) |c| {
            switch (c) {
                'a', 'á', 'o', 'ó', 'u', 'ú' => back_count += 1,
                'e', 'é', 'i', 'í' => front_count += 1,
                'ö', 'ő', 'ü', 'ű' => {
                    front_count += 1;
                    round_count += 1;
                },
                else => {},
            }
            if (c == 0xC3) continue; 
        }

        if (back_count > 0 and front_count == 0) return .Back;
        if (back_count == 0 and front_count > 0) {
            if (round_count > 0) return .FrontRounded;
            return .FrontUnrounded;
        }
        if (back_count > 0 and front_count > 0) return .Mixed;
        return .Neutral;
    }

    fn isHarmonyCompatible(stem: VowelHarmony, suffix: VowelHarmony) bool {
        if (suffix == .Neutral) return true;
        if (stem == .Mixed) return suffix == .Back; 
        if (stem == .Back) return suffix == .Back;
        if (stem == .FrontUnrounded) return (suffix == .FrontUnrounded or suffix == .Neutral);
        if (stem == .FrontRounded) return (suffix == .FrontRounded or suffix == .FrontUnrounded);
        return false;
    }

    fn addVec(dest: *[128]f32, src: *const [128]f32, weight: f32) void {
        for (0..128) |i| {
            dest[i] += src[i] * weight;
        }
    }

    fn modifyVec(vec: *[128]f32, shift: f32) void {
        for (0..128) |i| {
            vec[i] += shift;
        }
    }

    fn normalize(vec: *[128]f32) void {
        var sum: f32 = 0;
        for (vec) |x| sum += x * x;
        const mag = @sqrt(sum);
        if (mag > 0.0001) {
            for (0..128) |i| vec[i] /= mag;
        }
    }

    pub fn init(allocator: Allocator) !HungarianAGICore {
        var core = HungarianAGICore{
            .allocator = allocator,
            .lexicon = Lexicon.init(allocator),
            .morphology = try MorphologicalAnalyzer.init(allocator),
            .syntax = FunctionalSyntaxParser.init(allocator),
            .semantics = try SemanticProjector.init(allocator),
        };
        try core.bootstrapKnowledge();
        return core;
    }

    pub fn deinit(self: *HungarianAGICore) void {
        self.lexicon.deinit();
        self.morphology.deinit();
        self.semantics.deinit();
    }

    fn bootstrapKnowledge(self: *HungarianAGICore) !void {
        try self.lexicon.addEntry("ház", .Noun, .Back, &[_]SemanticFeature{.Concrete, .PhysicalObject, .Inanimate, .Location});
        try self.lexicon.addEntry("kutya", .Noun, .Back, &[_]SemanticFeature{.Concrete, .Animate, .PhysicalObject});
        try self.lexicon.addEntry("ember", .Noun, .FrontUnrounded, &[_]SemanticFeature{.Concrete, .Animate, .Human, .PhysicalObject});
        try self.lexicon.addEntry("lát", .Verb, .Back, &[_]SemanticFeature{.MentalProcess, .Animate});
        try self.lexicon.addEntry("fut", .Verb, .Back, &[_]SemanticFeature{.Motion, .Animate});
        try self.lexicon.addEntry("nagy", .Adjective, .Back, &[_]SemanticFeature{.Abstract});
        try self.lexicon.addEntry("hó", .Noun, .Back, &[_]SemanticFeature{.Concrete, .Inanimate, .PhysicalObject});
        try self.lexicon.addIrregularStem("hav", "hó");
        try self.lexicon.addEntry("tó", .Noun, .Back, &[_]SemanticFeature{.Concrete, .Location, .Inanimate});
        try self.lexicon.addIrregularStem("tav", "tó");
    }

    pub fn process(self: *HungarianAGICore, sentence: []const u8) !void {
        var token_iter = std.mem.tokenizeAny(u8, sentence, " .,!?");
        var analyses = std.ArrayList(MorphologicalAnalyzer.MorphResult).init(self.allocator);
        defer {
            for (analyses.items) |*a| {
                a.tags.deinit();
            }
            analyses.deinit();
        }

        while (token_iter.next()) |token| {
            const result = try self.morphology.analyze(&self.lexicon, token);
            try analyses.append(result);
        }

        const syntax_tree = try self.syntax.parse(analyses.items);
        defer syntax_tree.deinit();

        const stdout = std.io.getStdOut().writer();
        try stdout.print("=== PROCESSING: \"{s}\" ===\n", .{sentence});

        for (analyses.items, 0..) |an, i| {
            const emb = try self.semantics.project(an, &self.lexicon);
            const node = syntax_tree.items[i];

            try stdout.print("Token {d}: {s} -> Root: {s} [{s}] ", .{i, if (an.valid) "Valid" else "Invalid", an.root, @tagName(an.pos)});
            for (an.tags.items) |t| {
                try stdout.print("+{s}({s}) ", .{@tagName(t.type), t.value});
            }
            try stdout.print("\n  Syntax: Role={s}, Head={?d}\n", .{@tagName(node.dependency), node.head_index});
            try stdout.print("  Semantic Hash: {d:.4}\n", .{emb[0]}); 
        }
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    const allocator = gpa.allocator();
    defer _ = gpa.deinit();

    var core = try HungarianAGICore.init(allocator);
    defer core.deinit();

    try core.process("emberekben");
    try core.process("havat");
    try core.process("a nagy házban látom a kutyát");
}
